// Native tests for 0.25 phase D: the baked Paragon attack tracks (ASEnemyClipTracks.h, generated by Tools/paragon_clip_bake.py). They are switched on (BakedClipsOn=true, for the playtest); these tests hold the
// data to the same rules as the hand-made ability tracks so switching them on is safe, and prove that while they are off the game plays exactly the hand-made tracks. Not Unreal gameplay tests.
#include "../Source/AshenSpiral/Public/ASEnemyClipTracks.h"
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <set>
static long long Checks=0,Breaches=0; // Breaches: samples where a baked pose leaves the hand-made tracks' envelope (reported, not required)
static void Check(bool OK,const char* What) {++Checks;if(!OK) {std::cerr<<"FAILED: "<<What<<"\n";std::exit(1);}}
static unsigned Seed=25u;
static float Rand() {Seed=Seed*1664525u+1013904223u;return float((Seed>>8)&0xFFFF)/65535.f;}
static float Range(float A,float B) {return A+(B-A)*Rand();}
using namespace ASEnemyPose;
namespace ER=ASEnemyRules;
static float LimitFor(int C) { // the same per-channel limits as the hand-made tracks (Tests/enemy_pose_024_tests.cpp)
    return C==ChPlant?1.f:(C==ChBend||C==ChBendRoll?120.f:(C>=ChScaleX&&C<=ChScaleZ?.8f:(C==ChCrouch?30.f:(C==ChLeanX||C==ChLeanY?40.f:(C>=ChHandLX&&C<=ChHandRZ?140.f:(C==ChFootLX||C==ChFootRX?40.f:(C==ChStance?30.f:(C==ChGlow?3.f:120.f))))))));
}
int main() {
    Check(ClipCount>=1&&ClipCount<=24,"there is a small set of baked clips");
    // ---- Off means off: the game plays the hand-made tracks ----
    if(!BakedClipsOn) for(int A=0;A<ER::AbilityCount;++A) Check(&PlayedTrack(A)==&TrackFor(A)&&ClipIndexFor(TrackIndex(A))==-1,"with the baked clips off every ability plays its hand-made track");
    // ---- Which abilities have a clip, and that they are real ----
    std::set<int> Mapped;
    int WithClip=0;
    for(int Id=0;Id<ER::AbilityCount;++Id) {
        const int I=BakedClipIndexFor(TrackIndex(Id)); // the mapping, whether or not the switch is on
        if(I>=0) {Check(I<ClipCount,"a mapped clip index is real");Mapped.insert(I);++WithClip;}
        // Every ability id resolves to a clip or to its hand-made fallback, never to something empty or out of range.
        const Track& Baked=BakedTrack(Id);
        Check(&Baked==(I>=0?&ClipTrack(I):&TrackFor(Id)),"an ability with a clip plays it (when on), every other ability its hand-made track");
        Check(&PlayedTrack(Id)==(BakedClipsOn&&I>=0?&ClipTrack(I):&TrackFor(Id)),"what is played follows the switch");
        if(I<0&&Id!=ER::AbilityNone&&Id!=ER::AbilityDive&&Id!=ER::AbilityMolt) {int Curves=0;for(int K=0;K<MaxCurves&&TrackFor(Id).Curves[K].Channel>=0;++K) ++Curves;Check(Curves>=3,"an ability without a clip falls back to a real hand-made track");}
        if(Id==ER::AbilityDive||Id==ER::AbilityMolt||Id==ER::AbilityNone) Check(I<0,"the fliers' dive and molt and the empty ability have no clip");
        // Abilities that share a body language share the clip too (the elite mutations and the ward bosses follow their parent track).
        if(TrackIndex(Id)!=Id) Check(BakedClipIndexFor(TrackIndex(Id))==I,"a shared ability plays the clip of the track it shares");
    }
    Check(WithClip>=8,"most of the abilities have a baked clip");
    Check(Mapped.size()==size_t(ClipCount),"every baked track is used by some ability");
    // ---- Structure of every baked track, as for the hand-made ones ----
    for(int I=0;I<ClipCount;++I) {
        const Track& T=ClipTrack(I);std::set<int> Channels;bool Ended=false;int Curves=0;
        for(int K=0;K<MaxCurves;++K) {
            const Curve& C=T.Curves[K];
            if(C.Channel<0) {Ended=true;break;}
            ++Curves;
            Check(C.Channel<ChannelCount&&Channels.insert(C.Channel).second,"a baked curve drives a real channel, once");
            int N=0;while(N<MaxKeys&&C.Keys[N].T>=0.f) ++N;
            Check(N>=2&&N<MaxKeys,"a baked curve has between two keys and the maximum, with an end sentinel");
            Check(C.Keys[0].T==0.f&&C.Keys[0].V==0.f,"every baked curve starts at neutral at the very start");
            Check(C.Keys[N-1].T==TrackEnd&&C.Keys[N-1].V==0.f,"... and ends at neutral exactly at the end of the recovery");
            const float Limit=LimitFor(C.Channel);
            for(int Key=0;Key<N;++Key) {
                Check(std::isfinite(C.Keys[Key].V)&&std::fabs(C.Keys[Key].V)<=Limit,"every baked key stays inside its channel's range");
                if(Key) Check(C.Keys[Key].T>C.Keys[Key-1].T&&C.Keys[Key].T<=TrackEnd,"keys are strictly increasing inside the track");
            }
            float Previous=EvalCurve(C,0.f);
            for(float U=.005f;U<=TrackEnd+.0001f;U+=.005f) {const float V=EvalCurve(C,U);if(std::fabs(V-Previous)>Limit*.35f) std::cerr<<"clip "<<I<<" channel "<<C.Channel<<" at U "<<U<<": "<<Previous<<" -> "<<V<<"\n";
                Check(std::fabs(V-Previous)<=Limit*.35f,"a baked curve has no jumps");Previous=V;}
        }
        Check(Ended&&Curves>=8,"a baked track ends with a sentinel and drives a real set of channels");
        Check(Channels.count(ChPlant)==1&&Channels.count(ChGlow)==1,"it plants the feet and flares the glow like the hand-made tracks");
    }
    // ---- The solver stays sane over every baked track (finite, unit rotations, no crushed parts). The reach envelope, the floor and the head-over-torso rule are COUNTED, not required ----
    for(int I=0;I<ClipCount;++I) {
        const Track& T=ClipTrack(I);
        for(int Sample=0;Sample<600;++Sample) {
            const float U=Range(0.f,TrackEnd);float D[ChannelCount];Evaluate(T,U,D);
            RigInput In;In.Weight=Rand()<.5f?0.f:Range(0,1);In.GaitPhase=Range(0,6.2831853f);In.Step=std::sin(In.GaitPhase)*In.Weight;In.Seconds=Range(0,50);
            const float Angle=Range(0,6.2831853f);In.HeadingX=std::cos(Angle);In.HeadingY=std::sin(Angle);
            RigOut O;Solve(In,D,O);Xf World[SlotCount];ToFigureSpace(O,World);
            for(int Slot=0;Slot<SlotCount;++Slot) {
                const Xf& X=O.Part[Slot];
                Check(std::isfinite(X.Loc.X)&&std::isfinite(X.Loc.Y)&&std::isfinite(X.Loc.Z)&&std::isfinite(X.Scale.X)&&std::isfinite(X.Scale.Y)&&std::isfinite(X.Scale.Z),"every part transform is finite");
                Check(std::fabs(X.Rot.X*X.Rot.X+X.Rot.Y*X.Rot.Y+X.Rot.Z*X.Rot.Z+X.Rot.W*X.Rot.W-1.f)<.002f,"every rotation is a unit quaternion");
                Check(X.Scale.X>.19f&&X.Scale.Y>.19f&&X.Scale.Z>.19f&&X.Scale.X<3.f&&X.Scale.Y<3.f&&X.Scale.Z<3.f,"no part is crushed or blown up");
                const V3 P=World[Slot].Loc;
                if(!(P.X>-170.f&&P.X<260.f&&P.Y>-170.f&&P.Y<170.f&&P.Z>-12.f&&P.Z<340.f)) ++Breaches;
            }
            if(!(O.Part[BootL].Loc.Z>6.f&&O.Part[BootR].Loc.Z>6.f)) ++Breaches;
            if(!(World[Head].Loc.Z>World[Torso].Loc.Z&&World[Torso].Loc.Z>World[Pelvis].Loc.Z)) ++Breaches;
        }
    }
    std::cout<<"PASS: "<<Checks<<" baked-clip checks; the switch is honoured (off = the hand-made tracks, on = the clips), plus structure, limits, endpoints and solver sanity of every baked track.\nEnvelope breaches over "<<ClipCount*600<<" samples (the hand-made tracks have none; counted, not required: a part reaching past the old box or a boot dipping low is a look, never a crash; the clips are on, so watch for it in the playtest): "<<Breaches<<".\nShared rules only; whether the clips read well in game is unverified: that is what the playtest is for.\n";
}
